import json
import os
import re
from typing import Dict, List, Tuple


SECTION_RE = re.compile(r"^\[(.+)\]$")
CHOICE_RE = re.compile(r"^\s*\d+\.\s+")


def _split_sections(text: str) -> List[Tuple[str, List[str]]]:
    sections: List[Tuple[str, List[str]]] = []
    current_id = None
    current_lines: List[str] = []

    for raw_line in text.splitlines():
        line = raw_line.strip()
        m = SECTION_RE.match(line)
        if m:
            if current_id is not None:
                sections.append((current_id, [l for l in current_lines if l.strip()]))
            current_id = m.group(1).strip()
            current_lines = []
        else:
            if current_id is not None and line != "":
                current_lines.append(raw_line.strip())

    if current_id is not None:
        sections.append((current_id, [l for l in current_lines if l.strip()]))

    return sections


def _parse_line(line: str) -> Tuple[str, str, str]:
    if "->" not in line:
        raise ValueError(f"Line missing '->': {line}")
    left, target = line.rsplit("->", 1)
    target = target.strip()
    left = left.strip()
    if ":" in left:
        speaker, text = left.split(":", 1)
        return speaker.strip(), text.strip(), target
    return "", left, target


def _parse_choice(line: str) -> Tuple[str, str]:
    if "->" not in line:
        raise ValueError(f"Choice missing '->': {line}")
    left, target = line.rsplit("->", 1)
    target = target.strip()
    left = left.strip()
    left = CHOICE_RE.sub("", left).strip()
    return left, target


def parse_script(text: str) -> Dict[str, List[Dict[str, str]]]:
    sections = _split_sections(text)
    if not sections:
        return {"nodes": [], "edges": []}

    nodes: List[Dict[str, str]] = []
    edges: List[Dict[str, str]] = []

    for section_id, lines in sections:
        if not lines:
            nodes.append({"id": section_id, "text": "", "speaker": "", "type": "line"})
            continue

        is_choice = all(CHOICE_RE.match(l) for l in lines)
        if is_choice:
            nodes.append({"id": section_id, "text": "", "speaker": "", "type": "choice"})
            for line in lines:
                choice_text, target = _parse_choice(line)
                edges.append({"from": section_id, "to": target, "text": choice_text})
        else:
            if len(lines) != 1:
                raise ValueError(f"Line node '{section_id}' has multiple lines")
            speaker, text_line, target = _parse_line(lines[0])
            nodes.append({"id": section_id, "text": text_line, "speaker": speaker, "type": "line"})
            edges.append({"from": section_id, "to": target, "text": ""})

    ids = {n["id"] for n in nodes}
    targets = {e["to"] for e in edges}
    missing = sorted(t for t in targets if t not in ids)

    if missing == ["End"]:
        nodes.append({"id": "End", "text": "", "speaker": "", "type": "line"})
        ids.add("End")
        missing = []

    if missing:
        raise ValueError(f"Missing target nodes: {missing}")

    _validate_graph(nodes, edges, sections[0][0])
    return {"nodes": nodes, "edges": edges}


def _validate_graph(nodes: List[Dict[str, str]], edges: List[Dict[str, str]], start_id: str) -> None:
    ids = {n["id"] for n in nodes}
    for e in edges:
        if e["to"] not in ids:
            raise ValueError(f"Edge target missing: {e}")

    adjacency: Dict[str, List[str]] = {i: [] for i in ids}
    for e in edges:
        adjacency.setdefault(e["from"], []).append(e["to"])

    reachable = set()
    stack = [start_id]
    while stack:
        node_id = stack.pop()
        if node_id in reachable:
            continue
        reachable.add(node_id)
        for nxt in adjacency.get(node_id, []):
            if nxt not in reachable:
                stack.append(nxt)

    unreachable = sorted(ids - reachable)
    if unreachable:
        raise ValueError(f"Unreachable nodes from '{start_id}': {unreachable}")


def _escape_dot(text: str) -> str:
    return text.replace("\\", "\\\\").replace('"', '\\"')


def graph_to_dot(graph: Dict[str, List[Dict[str, str]]]) -> str:
    lines = ["digraph Dialogue {", "  node [shape=box];"]

    for node in graph["nodes"]:
        node_id = _escape_dot(node["id"])
        if node["type"] == "choice":
            label = f"{node['id']}\\n[choice]"
        else:
            if node.get("speaker"):
                label = f"{node['id']}\\n{node['speaker']}: {node['text']}"
            elif node.get("text"):
                label = f"{node['id']}\\n{node['text']}"
            else:
                label = node['id']
        label = _escape_dot(label)
        lines.append(f'  "{node_id}" [label="{label}"];')

    for edge in graph["edges"]:
        src = _escape_dot(edge["from"])
        dst = _escape_dot(edge["to"])
        label = _escape_dot(edge.get("text", ""))
        if label:
            lines.append(f'  "{src}" -> "{dst}" [label="{label}"];')
        else:
            lines.append(f'  "{src}" -> "{dst}";')

    lines.append("}")
    return "\n".join(lines) + "\n"


def main() -> None:
    script_path = "/app/script.txt"
    json_path = "/app/dialogue.json"
    dot_path = "/app/dialogue.dot"

    with open(script_path, "r", encoding="utf-8") as f:
        text = f.read()

    graph = parse_script(text)

    with open(json_path, "w", encoding="utf-8") as f:
        json.dump(graph, f, indent=2, ensure_ascii=True)
        f.write("\n")

    dot = graph_to_dot(graph)
    with open(dot_path, "w", encoding="utf-8") as f:
        f.write(dot)


if __name__ == "__main__":
    main()
